wrong.code:
// Looks safe. Is not.
DB::transaction(function () use ($productId, $userId) {
    $product = Product::find($productId);          // plain SELECT: reads the snapshot / old value
    if ($product->stock < 1) {
        throw new OutOfStock();
    }
    $product->decrement('stock');                  // both requests reach here
    Order::create(['user_id' => $userId, 'product_id' => $productId]);
});

right.code:
// Fix 1: pessimistic lock — hand on the seat
DB::transaction(function () use ($productId, $userId) {
    $product = Product::whereKey($productId)->lockForUpdate()->first();   // SELECT ... FOR UPDATE
    if ($product->stock < 1) {
        throw new OutOfStock();
    }
    $product->decrement('stock');
    Order::create(['user_id' => $userId, 'product_id' => $productId]);
}, attempts: 3);   // retry on deadlock

// Fix 2: atomic conditional write — no lock, one statement
$sold = Product::whereKey($productId)->where('stock', '>', 0)->decrement('stock');
if ($sold === 0) {
    throw new OutOfStock();
}
Order::create([...]);   // wrap both in a transaction so a failed order restores stock

// Fix 3: optimistic — version column
$p = Product::find($productId);
$updated = Product::whereKey($p->id)->where('version', $p->version)
    ->update(['stock' => $p->stock - 1, 'version' => $p->version + 1]);
if ($updated === 0) { /* someone else changed it: reload and retry, or tell the user */ }

-- The SQL behind fix 1 (MySQL):
START TRANSACTION;
SELECT * FROM products WHERE id = 42 FOR UPDATE;   -- T2 running the same line now WAITS here
UPDATE products SET stock = stock - 1 WHERE id = 42;
INSERT INTO orders (...) VALUES (...);
COMMIT;                                            -- T2 wakes, sees stock = 0, throws OutOfStock

