public function transfer(int $fromId, int $toId, int $amountMinor): void
{
    if ($fromId === $toId || $amountMinor <= 0) throw new InvalidTransfer();
    DB::transaction(function () use ($fromId, $toId, $amountMinor) {
        [$firstId, $secondId] = $fromId < $toId ? [$fromId, $toId] : [$toId, $fromId];
        $accounts = Account::whereIn('id', [$firstId, $secondId])
            ->orderBy('id')->lockForUpdate()->get()->keyBy('id');   // consistent lock order
        $from = $accounts[$fromId]; $to = $accounts[$toId];
        if ($from->balance_minor < $amountMinor) throw new InsufficientFunds();
        $from->decrement('balance_minor', $amountMinor);
        $to->increment('balance_minor', $amountMinor);
        LedgerEntry::create(['account_id' => $fromId, 'delta' => -$amountMinor, 'ref' => ...]);
        LedgerEntry::create(['account_id' => $toId,   'delta' =>  $amountMinor, 'ref' => ...]);
    }, attempts: 3);
}

practice.task:
Explain what goes wrong here and rewrite it:

DB::transaction(function () use ($order) {
    $order->update(['status' => 'paid']);
    $this->gateway->charge($order);        // HTTP call, 2–8 seconds
    SendReceipt::dispatch($order);
});

practice.solution:
// Problem 1: the row lock on orders is held for the whole gateway call — other requests touching that order (and possibly gap-locked neighbours) wait seconds.
// Problem 2: SendReceipt may run before the transaction commits (or after a rollback) and see status != paid.
// Problem 3: if the gateway succeeds and the transaction then fails, the customer is charged with no paid order.

$charge = $this->gateway->charge($order, idempotencyKey: $order->payment_key);   // outside the transaction
DB::transaction(function () use ($order, $charge) {
    $order->update(['status' => 'paid', 'charge_id' => $charge->id]);
    Payment::create([...]);
});
SendReceipt::dispatch($order)->afterCommit();   // or dispatch after the transaction block
// Reconciliation job: charges with no paid order → refund or mark. This is where idempotency keys earn their keep.
